<template>
  <div class="relative h-full w-full">
    <div ref="host" class="h-full w-full" />

    <RouteMapFallback
      v-if="state === 'error'"
      :stops="stops"
      class="absolute inset-0"
      @stop-tap="(seq: number) => emit('stop-tap', seq)"
    />
  </div>
</template>

<script setup lang="ts">
import RouteMapFallback from "./RouteMapFallback.vue";
import { markerColorFor } from "../route.visuals";
import type { RouteMapStop } from "../route.types";

const props = defineProps<{ stops: RouteMapStop[]; apiKey: string }>();
const emit = defineEmits<{ "stop-tap": [seq: number] }>();

const host = ref<HTMLElement | null>(null);
const state = ref<"loading" | "ready" | "error">("loading");

const ALGIERS = { lat: 36.7538, lng: 3.0588 };

onMounted(async () => {
  try {
    const { Loader } = await import("@googlemaps/js-api-loader");
    const loader = new Loader({ apiKey: props.apiKey, libraries: ["geometry"] });
    const google = (await loader.load()) as any;
    if (!host.value) return;

    const points = props.stops.filter((s) => s.lat != null && s.lng != null);
    const first = points[0];
    const map = new google.maps.Map(host.value, {
      disableDefaultUI: true,
      clickableIcons: false,
      center: first ? { lat: first.lat, lng: first.lng } : ALGIERS,
      zoom: 13,
    });

    const bounds = new google.maps.LatLngBounds();
    const path: Array<{ lat: number; lng: number }> = [];

    for (const stop of points) {
      const position = { lat: stop.lat, lng: stop.lng };
      path.push(position);
      bounds.extend(position);

      const marker = new google.maps.Marker({
        position,
        map,
        label: { text: String(stop.seq), color: "#ffffff", fontWeight: "700" },
        icon: {
          path: google.maps.SymbolPath.CIRCLE,
          scale: 14,
          fillColor: markerColorFor(stop.status),
          fillOpacity: 1,
          strokeColor: "#ffffff",
          strokeWeight: 2,
        },
      });
      marker.addListener("click", () => emit("stop-tap", stop.seq));
    }

    if (path.length > 1) {
      new google.maps.Polyline({
        path,
        map,
        strokeColor: "#0b73ff",
        strokeOpacity: 0.9,
        strokeWeight: 4,
      });
    }
    if (points.length) map.fitBounds(bounds, 56);

    state.value = "ready";
  } catch {
    state.value = "error";
  }
});
</script>
