<template>
  <label
    class="flex min-w-0 items-center gap-2 rounded-full border border-[rgba(222,230,244,0.9)] bg-white/90 px-3.5 py-2.5 shadow-[0_10px_24px_rgba(31,58,107,0.12)] backdrop-blur-md"
  >
    <ILucideSearch class="h-[18px] w-[18px] shrink-0 text-[#9aa6c4]" />
    <input
      ref="field"
      :value="modelValue"
      type="search"
      placeholder="Search stop or address"
      class="min-w-0 flex-1 border-0 bg-transparent text-[14px] text-[#11172e] outline-none placeholder:text-[#9aa6c4]"
      @input="$emit('update:modelValue', ($event.target as HTMLInputElement).value)"
    />
    <button
      v-if="modelValue"
      type="button"
      class="shrink-0 text-[#9aa6c4]"
      @click="$emit('update:modelValue', '')"
    >
      <ILucideX class="h-[18px] w-[18px]" />
    </button>
  </label>
</template>

<script setup lang="ts">
defineProps<{ modelValue: string }>();
defineEmits<{ "update:modelValue": [value: string] }>();

const field = ref<HTMLInputElement | null>(null);

onMounted(() => field.value?.focus());
</script>
