<template>
  <div class="relative h-full w-full overflow-hidden">
    <component
      :is="mapComponent"
      v-if="canRenderMap && mapComponent"
      :stops="stops"
      :api-key="apiKey"
      @stop-tap="(seq: number) => $emit('stop-tap', seq)"
    />

    <RouteMapFallback
      v-else
      :stops="stops"
      @stop-tap="(seq: number) => $emit('stop-tap', seq)"
    />
  </div>
</template>

<script setup lang="ts">
import RouteMapFallback from "./RouteMapFallback.vue";
import type { RouteMapStop } from "../route.types";

defineProps<{ stops: RouteMapStop[] }>();
defineEmits<{ "stop-tap": [seq: number] }>();

const apiKey = import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string | undefined;
const device = getDevice();
const useNative = !!(device.android && device.capacitor);
const canRenderMap = useNative || !!apiKey;

const mapComponent = !canRenderMap
  ? null
  : useNative
    ? defineAsyncComponent(() => import("./RouteMapNative.vue"))
    : defineAsyncComponent(() => import("./RouteMapWeb.vue"));
</script>
