<template>
  <div class="relative h-full w-full">
    <div
      id="route-map-container"
      ref="host"
      class="absolute inset-0"
      :style="{ visibility: state === 'ready' ? 'visible' : 'hidden' }"
    />

    <div
      v-if="state === 'loading'"
      class="absolute inset-0 flex items-center justify-center bg-[#f5f9ff]"
    >
      <F7Preloader />
    </div>

    <RouteMapFallback
      v-else-if="state === 'error'"
      :stops="stops"
      class="absolute inset-0"
      @stop-tap="(seq: number) => emit('stop-tap', seq)"
    />
  </div>
</template>

<script setup lang="ts">
import RouteMapFallback from "./RouteMapFallback.vue";
import { markerColorFor } from "../route.visuals";
import type { RouteMapStop } from "../route.types";

const props = defineProps<{ stops: RouteMapStop[] }>();
const emit = defineEmits<{ "stop-tap": [seq: number] }>();

const host = ref<HTMLElement | null>(null);
const state = ref<"loading" | "ready" | "error">("loading");
let sdk: any = null;

function markerIcon(seq: number, color: string): string {
  const size = 64;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) return "";
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, size / 2 - 6, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = "#ffffff";
  ctx.stroke();
  ctx.fillStyle = "#ffffff";
  ctx.font = "700 28px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(String(seq), size / 2, size / 2 + 1);
  return canvas.toDataURL("image/png");
}

async function syncBounds() {
  if (!host.value || !sdk) return;
  const rect = host.value.getBoundingClientRect();
  await sdk.updateMapBounds({
    x: Math.round(rect.left),
    y: Math.round(rect.top),
    width: Math.round(rect.width),
    height: Math.round(rect.height),
  });
}

async function buildMarkers() {
  const points = props.stops.filter((s) => s.lat != null && s.lng != null);
  for (const stop of points) {
    await sdk.addCustomMarker({
      position: { latitude: stop.lat, longitude: stop.lng },
      iconImage: markerIcon(stop.seq, markerColorFor(stop.status)),
      title: String(stop.seq),
    });
  }
  const first = points[0];
  if (first) {
    await sdk.moveCamera({ latitude: first.lat, longitude: first.lng, zoom: 13 });
  }
}

const onResize = () => void syncBounds();

onMounted(async () => {
  try {
    const mod = await import("capacitor-maps-sdk");
    sdk = mod.CapacitorMapSdk;
    document.body.classList.add("route-map-transparent");
    await sdk.initialize({ containerId: "route-map-container", showLocationButton: true });
    await nextTick();
    await syncBounds();
    await sdk.enableMapInteraction();
    await buildMarkers();
    sdk.addListener("onMarkerClick", (data: { latitude: number; longitude: number }) => {
      const hit = props.stops.find(
        (s) =>
          s.lat != null &&
          s.lng != null &&
          Math.abs(s.lat - data.latitude) < 0.0001 &&
          Math.abs(s.lng - data.longitude) < 0.0001,
      );
      if (hit) emit("stop-tap", hit.seq);
    });
    window.addEventListener("resize", onResize);
    state.value = "ready";
  } catch {
    state.value = "error";
  }
});

watch(
  () => props.stops,
  async () => {
    if (!sdk || state.value !== "ready") return;
    await sdk.clearMarkers();
    await buildMarkers();
  },
);

onBeforeUnmount(async () => {
  window.removeEventListener("resize", onResize);
  document.body.classList.remove("route-map-transparent");
  try {
    if (sdk) await sdk.destroyMap();
  } catch {
    void 0;
  }
});
</script>
